NEW_FILES = {
 "config/safevoice-extension.ttl": "@prefix cdm: <https://w3id.org/dsip/cdm/> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix hds: <https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl#> .\n@prefix owl: <http://www.w3.org/2002/07/owl#> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix schema: <http://schema.org/> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\n# SafeVoice extension of the HDS Common Data Model: terms that are specific to this application\n# (human-trafficking source reporting). Proposed to the HDS team through the FieldLab fork; none of\n# these terms may be moved into the core mapping. Every cdm: term used in config/mapping_*.yml must be\n# declared here (tests/test_hds_mapping.py checks this).\n\n<https://w3id.org/dsip/cdm/>\n    a owl:Ontology ;\n    rdfs:label \"SafeVoice extension of the HDS CDM\"@en ;\n    rdfs:comment \"Application-specific terms of the SafeVoice field lab. Draft: to be reviewed by the HDS team.\"@en .\n\n# ---- Locations ----\ncdm:departureLocation a owl:ObjectProperty ;\n    rdfs:label \"departure location\"@en ;\n    rdfs:comment \"Role of a location on an incident: where the journey started. A sub-property of schema:location; both are written because the CDM has a single location property.\"@en ;\n    rdfs:subPropertyOf schema:location ;\n    rdfs:domain hds:Incident .\ncdm:destinationLocation a owl:ObjectProperty ;\n    rdfs:label \"destination location\"@en ;\n    rdfs:comment \"Role of a location on an incident: where the journey ended or was meant to end. A sub-property of schema:location.\"@en ;\n    rdfs:subPropertyOf schema:location ;\n    rdfs:domain hds:Incident .\ncdm:currentLocation a owl:ObjectProperty ;\n    rdfs:label \"current location\"@en ;\n    rdfs:comment \"Where a victim currently is.\"@en ;\n    rdfs:domain prov:Agent .\ncdm:village a owl:DatatypeProperty ;\n    rdfs:label \"village\"@en ;\n    rdfs:range xsd:string .\ncdm:locationType a owl:DatatypeProperty ;\n    rdfs:label \"location type\"@en ;\n    rdfs:comment \"Free choice from a drop-down, for example refugee or IDP camp, human trafficking or smuggling camp.\"@en ;\n    rdfs:range xsd:string .\ncdm:departureDate a owl:DatatypeProperty ;\n    rdfs:label \"departure date\"@en ;\n    rdfs:range xsd:date .\ncdm:arrivalDate a owl:DatatypeProperty ;\n    rdfs:label \"arrival date\"@en ;\n    rdfs:range xsd:date .\n\n# ---- People ----\ncdm:age a owl:DatatypeProperty ;\n    rdfs:label \"age\"@en ;\n    rdfs:comment \"Age of the victim in years.\"@en ;\n    rdfs:range xsd:integer .\ncdm:situation a owl:DatatypeProperty ;\n    rdfs:label \"situation\"@en ;\n    rdfs:comment \"Situation of the victim, for example in captivity or en route.\"@en ;\n    rdfs:range xsd:string .\ncdm:numberOfTraffickers a owl:DatatypeProperty ;\n    rdfs:label \"number of traffickers\"@en ;\n    rdfs:range xsd:integer .\n\n# ---- Record keeping ----\ncdm:recordId a owl:DatatypeProperty ;\n    rdfs:label \"record ID\"@en ;\n    rdfs:comment \"Identifier of the submitted record in the SafeVoice application.\"@en ;\n    rdfs:range xsd:string .\ncdm:dateReceived a owl:DatatypeProperty ;\n    rdfs:label \"date received\"@en ;\n    rdfs:range xsd:date .\ncdm:dateRecorded a owl:DatatypeProperty ;\n    rdfs:label \"date recorded\"@en ;\n    rdfs:range xsd:date .\ncdm:correctionReason a owl:DatatypeProperty ;\n    rdfs:label \"correction reason\"@en ;\n    rdfs:comment \"Why a record was corrected. Used together with prov:wasRevisionOf, which points to the incident it corrects.\"@en ;\n    rdfs:range xsd:string .\ncdm:mappingVersion a owl:DatatypeProperty ;\n    rdfs:label \"mapping version\"@en ;\n    rdfs:comment \"Fingerprint of the mapping files that produced the data (see prov:Activity).\"@en ;\n    rdfs:range xsd:string .\n",
 "config/safevoice-extension-shapes.ttl": "@prefix cdm: <https://w3id.org/dsip/cdm/> .\n@prefix svshapes: <https://w3id.org/dsip/cdm/shapes#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix hds: <https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl#> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix schema: <http://schema.org/> .\n@prefix sh: <http://www.w3.org/ns/shacl#> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\n# Value types for the SafeVoice extension terms (config/safevoice-extension.ttl). Like the HDS shapes,\n# all properties are optional; these shapes only check types.\n\nsvshapes:IncidentExtensionShape a sh:NodeShape ;\n    sh:targetClass hds:Incident ;\n    sh:property [ sh:path cdm:departureLocation ; sh:class dcterms:Location ] ;\n    sh:property [ sh:path cdm:destinationLocation ; sh:class dcterms:Location ] ;\n    sh:property [ sh:path cdm:dateReceived ; sh:datatype xsd:date ] ;\n    sh:property [ sh:path cdm:dateRecorded ; sh:datatype xsd:date ] ;\n    sh:property [ sh:path cdm:recordId ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path cdm:correctionReason ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path prov:wasRevisionOf ; sh:nodeKind sh:IRI ] ;\n    sh:property [ sh:path prov:wasGeneratedBy ; sh:class prov:Activity ] .\n\nsvshapes:PersonExtensionShape a sh:NodeShape ;\n    sh:targetClass prov:Agent ;\n    sh:property [ sh:path cdm:age ; sh:datatype xsd:integer ; sh:minInclusive 0 ; sh:maxInclusive 120 ] ;\n    sh:property [ sh:path cdm:situation ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path cdm:numberOfTraffickers ; sh:datatype xsd:integer ; sh:minInclusive 1 ] ;\n    sh:property [ sh:path cdm:currentLocation ; sh:class dcterms:Location ] .\n\nsvshapes:LocationExtensionShape a sh:NodeShape ;\n    sh:targetClass dcterms:Location ;\n    sh:property [ sh:path cdm:village ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path cdm:locationType ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path cdm:departureDate ; sh:datatype xsd:date ] ;\n    sh:property [ sh:path cdm:arrivalDate ; sh:datatype xsd:date ] ;\n    sh:property [ sh:path schema:latitude ; sh:datatype xsd:float ; sh:minInclusive -90 ; sh:maxInclusive 90 ] ;\n    sh:property [ sh:path schema:longitude ; sh:datatype xsd:float ; sh:minInclusive -180 ; sh:maxInclusive 180 ] .\n\nsvshapes:ActivityShape a sh:NodeShape ;\n    sh:targetClass prov:Activity ;\n    sh:property [ sh:path prov:endedAtTime ; sh:datatype xsd:dateTime ] ;\n    sh:property [ sh:path cdm:mappingVersion ; sh:datatype xsd:string ] .\n",
 "src/storage/admin.py": "\"\"\"Look at and clean up the AllegroGraph repository. Run from the repository root:\n\n    python -m src.storage.admin graphs               list the graphs and their sizes\n    python -m src.storage.admin drop-user NAME       delete one user's graph (asks you to type the name)\n\nEach SafeVoice user's triples live in their own named graph (see ingest.graph_for_source), so one\nuser's data can be removed without touching anyone else's. After a CDM or mapping change: drop the\nuser's graph, then `python -m ui.resync --user NAME` to send the records again.\n\nTriples uploaded by the very first version of the pipeline (before one graph per user) are in the\ndefault graph and are NOT touched here: the repository may be shared with other field labs.\n\"\"\"\nimport sys\n\nfrom src.storage import ingest\n\n\ndef list_graphs(conn):\n    \"\"\"[(graph IRI, number of triples or None)] for every named graph.\"\"\"\n    rows = []\n    for ctx in conn.getContextIDs():\n        try:\n            size = conn.size(ctx)\n        except Exception:  # noqa: BLE001\n            size = None\n        rows.append((str(ctx).strip(\"<>\"), size))\n    return sorted(rows)\n\n\ndef drop_user_graph(conn, username):\n    \"\"\"Delete the graph of one user. Raises ValueError for anything but a plain user name.\"\"\"\n    graph = ingest.graph_for_source(username)\n    conn.remove(None, None, None, contexts=[conn.createURI(graph)])\n    return graph\n\n\ndef main(argv=None):\n    argv = list(sys.argv[1:] if argv is None else argv)\n    if not argv or argv[0] not in (\"graphs\", \"drop-user\"):\n        print(__doc__)\n        return 2\n    missing = ingest.missing_settings()\n    if missing:\n        print(\"Missing in .env:\", \", \".join(missing))\n        return 1\n    conn = ingest.connect()\n    try:\n        if argv[0] == \"graphs\":\n            for graph, size in list_graphs(conn):\n                print(f\"{size if size is not None else '?':>8}  {graph}\")\n            return 0\n        if len(argv) < 2:\n            print(\"Usage: python -m src.storage.admin drop-user NAME\")\n            return 2\n        name = argv[1]\n        graph = ingest.graph_for_source(name)\n        if input(f\"This deletes ALL triples in <{graph}>. Type the user name to confirm: \").strip() != name:\n            print(\"Cancelled.\")\n            return 1\n        drop_user_graph(conn, name)\n        print(f\"Deleted graph <{graph}>.\")\n        return 0\n    finally:\n        conn.close()\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
 "ui/resync.py": "\"\"\"Send stored records through the pipeline again, for example after the mapping or the CDM changed.\n\n    python -m ui.resync                     all records of all users\n    python -m ui.resync --user alice        one user\n    python -m ui.resync --only-unsynced     only records that are not in the database yet\n\nThe uploads add triples to the user's graph. To replace old data: python -m src.storage.admin drop-user alice\nfirst. The SQLite database stays the source of truth.\n\"\"\"\nimport sys\n\nfrom ui import store\n\n\ndef main(argv=None):\n    argv = list(sys.argv[1:] if argv is None else argv)\n    user = argv[argv.index(\"--user\") + 1] if \"--user\" in argv else None\n    synced, failed = store.resync_all(user, only_unsynced=\"--only-unsynced\" in argv)\n    print(f\"Sent again: {synced} in the database, {failed} failed (see data/audit/audit.log for the reasons).\")\n    return 0 if not failed else 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
 "ui/mockdata.py": "\"\"\"Create synthetic records for demos, tests and the HDS portal. Nothing here is real data.\n\n    python -m ui.mockdata --user alice --records 20            create and upload\n    python -m ui.mockdata --user alice --records 20 --no-upload   create only (upload later with Retry)\n\nThe records go through the normal path (SQLite, cleaning, RDF, shape check, AllegroGraph), so they also\nprove that the mapping produces valid HDS data. Every title starts with \"[MOCK]\" and every narrative says\nit is synthetic. `--user` must be a user from SAFEVOICE_USERS to see the data in the app.\n\"\"\"\nimport os\nimport random\nimport sys\nfrom datetime import date, timedelta\n\nimport pandas as pd\n\nfrom ui import store\n\nDROPDOWNS = os.path.join(\"config\", \"UI_drop_downs.csv\")\n_FALLBACK = {\"Country\": [\"Sudan\", \"Uganda\", \"Kenya\", \"Ethiopia\"], \"Gender\": [\"Female\", \"Male\", \"Other\"],\n             \"Situation\": [\"In captivity\", \"En route\", \"Other\"], \"Nationality\": [\"Ethiopia\", \"Eritrea\", \"Sudan\"],\n             \"Type of location\": [\"Refugee/IDP Camp\", \"Human Trafficking/Smuggling Camp\"]}\n_TOWNS = [\"Mock Town A\", \"Mock Town B\", \"Mock Village C\", \"Mock City D\"]\n\n\ndef _options():\n    try:\n        frame = pd.read_csv(DROPDOWNS, dtype=str, encoding=\"utf-8-sig\")\n        return {c: frame[c].dropna().tolist() for c in _FALLBACK if c in frame.columns} | {\n            c: v for c, v in _FALLBACK.items() if c not in frame.columns}\n    except (OSError, ValueError):\n        return dict(_FALLBACK)\n\n\ndef _place(rng, opts, start):\n    return {\"country\": rng.choice(opts[\"Country\"]), \"town\": rng.choice(_TOWNS), \"date\": start,\n            \"latitude\": round(rng.uniform(-5, 20), 3), \"longitude\": round(rng.uniform(25, 45), 3),\n            \"type\": rng.choice(opts[\"Type of location\"])}\n\n\ndef make_data(rng, opts, full):\n    \"\"\"Structured data for one record; with full=False most optional fields stay empty.\"\"\"\n    if not full:\n        return {\"victim\": {\"number_of_victims\": rng.randint(1, 4)}, \"incident\": {}}\n    start = date(2026, 1, 1) + timedelta(days=rng.randint(0, 200))\n    return {\n        \"victim\": {\"number_of_victims\": rng.randint(1, 6), \"nationality\": rng.choice(opts[\"Nationality\"]),\n                   \"gender\": rng.choice(opts[\"Gender\"]), \"age\": rng.randint(8, 60),\n                   \"situation\": rng.choice(opts[\"Situation\"])},\n        \"incident\": {\"departure\": _place(rng, opts, start),\n                     \"destination\": _place(rng, opts, start + timedelta(days=rng.randint(1, 30)))},\n        \"trafficker\": {\"number_of_traffickers\": rng.randint(1, 3), \"name\": \"\", \"nationality\": rng.choice(opts[\"Nationality\"]),\n                       \"description\": \"Synthetic description.\"},\n        \"publication\": {\"name\": \"Mock Gazette\", \"link\": \"https://example.org/mock\", \"date\": start},\n    }\n\n\ndef generate(user, records=20, seed=7, upload=True):\n    \"\"\"Create 2 topics and `records` synthetic records for `user`. Returns the list of stored records.\"\"\"\n    rng, opts = random.Random(seed), _options()\n    if not upload:\n        original, store.run_pipeline = store.run_pipeline, lambda df: (df, \"Failed: Ingestion Error\")\n    try:\n        topics = [store.create_topic(user, f\"[MOCK] Topic {n}\", \"Synthetic topic for demos.\") for n in \"AB\"]\n        stored = []\n        for i in range(1, records + 1):\n            topic = topics[i % 2]\n            corrects = None\n            if i % 5 == 0 and stored:  # every fifth record corrects an earlier one in the same topic\n                earlier = [r for r in stored if r[\"topic_id\"] == topic[\"id\"]]\n                corrects = earlier[-1][\"id\"] if earlier else None\n            stored.append(store.submit_record(\n                user, topic[\"id\"], f\"[MOCK] Record {i}\",\n                f\"Synthetic example record {i}. It is not based on a real case.\",\n                make_data(rng, opts, full=i % 4 != 0), corrects=corrects,\n                reason=\"Synthetic correction.\" if corrects else \"\"))\n        return stored\n    finally:\n        if not upload:\n            store.run_pipeline = original\n\n\ndef main(argv=None):\n    argv = list(sys.argv[1:] if argv is None else argv)\n    if \"--user\" not in argv:\n        print(__doc__)\n        return 2\n    user = argv[argv.index(\"--user\") + 1]\n    count = int(argv[argv.index(\"--records\") + 1]) if \"--records\" in argv else 20\n    stored = generate(user, count, upload=\"--no-upload\" not in argv)\n    synced = sum(r[\"sync_status\"] == store.SYNCED for r in stored)\n    print(f\"Created {len(stored)} synthetic records for {user}: {synced} in the database.\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
 "src/fdp/__init__.py": "",
 "src/fdp/metadata.py": "\"\"\"Draft FAIR Data Point metadata for the SafeVoice data (W2-04). Run from the repository root:\n\n    python -m src.fdp.metadata                 writes data/fdp/safevoice-metadata.ttl\n\nOne catalogue for SafeVoice and one dcat:Dataset per user graph, each with a distribution that points at\nthe AllegroGraph repository. The graph is checked against the HDS shapes (catalogue, dataset, publisher,\nlicence). This only PREPARES the metadata: registering it needs the endpoint and profile of the FDP\nthat your professor's team points you to. Settings in .env (all optional):\n\n    SAFEVOICE_PUBLISHER      name of the publishing organisation (default \"SafeVoice field lab\")\n    SAFEVOICE_LICENSE        IRI of the licence or rights statement (default: none; a legal decision)\n    SAFEVOICE_METADATA_LANG  language of titles and descriptions (default en)\n\nIt describes the datasets, never their content.\n\"\"\"\nimport os\nimport sys\nfrom datetime import datetime, timezone\n\nfrom rdflib import Graph, Literal, Namespace, URIRef\nfrom rdflib.namespace import DCTERMS, FOAF, PROV, RDF, RDFS, XSD\n\nfrom src.storage import ingest\nfrom src.validation import shacl\n\nDCAT = Namespace(\"http://www.w3.org/ns/dcat#\")\nEX = Namespace(\"https://w3id.org/dsip/eepa/\")\nCDM_IRI = URIRef(\"https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl\")\nOUT = os.path.join(\"data\", \"fdp\", \"safevoice-metadata.ttl\")\n\n\ndef build_metadata(users, publisher=None, license_iri=None, language=None, endpoint=None, now=None):\n    \"\"\"RDF graph with one catalogue and one dataset (plus distribution) per user.\"\"\"\n    publisher = publisher or os.getenv(\"SAFEVOICE_PUBLISHER\", \"SafeVoice field lab\")\n    license_iri = license_iri if license_iri is not None else os.getenv(\"SAFEVOICE_LICENSE\", \"\")\n    language = language or os.getenv(\"SAFEVOICE_METADATA_LANG\", \"en\")\n    now = now or datetime.now(timezone.utc).strftime(\"%Y-%m-%dT%H:%M:%SZ\")\n    if endpoint is None:\n        s = ingest._settings()\n        endpoint = f\"https://{s['host']}/repositories/{s['repo']}\" if s[\"host\"] and s[\"repo\"] else \"\"\n\n    g = Graph()\n    for prefix, ns in ((\"dcat\", DCAT), (\"dcterms\", DCTERMS), (\"prov\", PROV), (\"foaf\", FOAF), (\"ex\", EX)):\n        g.bind(prefix, ns)\n    agent, catalog = EX.agent_publisher, EX.catalog_safevoice\n    g.add((agent, RDF.type, PROV.Agent))\n    g.add((agent, FOAF.name, Literal(publisher)))\n    g.add((catalog, RDF.type, DCAT.Catalog))\n    g.add((catalog, DCTERMS.title, Literal(\"SafeVoice catalogue\", lang=language)))\n    g.add((catalog, DCTERMS.description, Literal(\"Human-trafficking source reports collected with SafeVoice.\", lang=language)))\n    g.add((catalog, DCTERMS.publisher, agent))\n    g.add((catalog, DCTERMS.conformsTo, CDM_IRI))\n    g.add((catalog, PROV.generatedAtTime, Literal(now, datatype=XSD.dateTime)))\n    if license_iri:\n        g.add((URIRef(license_iri), RDF.type, DCTERMS.RightsStatement))\n        g.add((catalog, DCTERMS.license, URIRef(license_iri)))\n    for user in sorted(users):\n        graph_iri = ingest.graph_for_source(user)\n        dataset, dist = EX[f\"dataset_{user}\"], EX[f\"distribution_{user}\"]\n        g.add((dataset, RDF.type, DCAT.Dataset))\n        g.add((dataset, DCTERMS.identifier, Literal(f\"safevoice-{user}\")))\n        g.add((dataset, DCTERMS.title, Literal(f\"SafeVoice records of {user}\", lang=language)))\n        g.add((dataset, DCTERMS.description, Literal(\n            f\"Incidents reported by {user}, as RDF in the named graph {graph_iri}.\", lang=language)))\n        g.add((dataset, DCTERMS.isPartOf, catalog))\n        g.add((dataset, DCTERMS.publisher, agent))\n        g.add((dataset, DCTERMS.conformsTo, CDM_IRI))\n        g.add((dataset, DCAT.version, Literal(\"1.0\")))\n        g.add((dataset, PROV.generatedAtTime, Literal(now, datatype=XSD.dateTime)))\n        g.add((dataset, DCAT.distribution, dist))\n        if license_iri:\n            g.add((dataset, DCTERMS.license, URIRef(license_iri)))\n        g.add((dist, RDF.type, DCAT.Distribution))\n        g.add((dist, DCTERMS.title, Literal(\"SPARQL access to the AllegroGraph repository\", lang=language)))\n        g.add((dist, DCTERMS.description, Literal(f\"Named graph {graph_iri}.\", lang=language)))\n        if endpoint:\n            g.add((dist, DCAT.accessURL, URIRef(endpoint)))\n    return g\n\n\ndef main(argv=None):\n    from ui import auth\n    users = list(auth._allowed_users())\n    if not users:\n        print(\"No users in SAFEVOICE_USERS: nothing to describe.\")\n        return 1\n    g = build_metadata(users)\n    conforms, problems = shacl.validate_graph(g)\n    if not conforms:\n        print(\"The metadata does not conform to the HDS shapes:\", problems)\n        return 1\n    os.makedirs(os.path.dirname(OUT), exist_ok=True)\n    g.serialize(OUT, format=\"turtle\")\n    print(f\"Wrote {OUT}: 1 catalogue, {len(users)} dataset(s). It conforms to the HDS shapes.\")\n    if not os.getenv(\"SAFEVOICE_LICENSE\"):\n        print(\"Note: no SAFEVOICE_LICENSE set, so no licence is stated. Agree the licence or rights statement first.\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
 "docs/DEPLOYMENT_AND_PRIVACY.md": "# Deployment checklist and privacy notes\n\nWritten for the HDS deployment step (where AllegroGraph runs, local provider, local FDP). It lists what the\napplication does itself and what the host has to provide. Fill in the \"Decision\" column with the team.\n\n## 1. Decisions for the deployment session\n\n| Question | Why it matters | Decision |\n|---|---|---|\n| Where does AllegroGraph run (Kenya, Uganda, Ethiopia or Belgium)? | Decides which data-protection law applies and who can be compelled to hand over data | |\n| Which local provider hosts it? | Needs the controls in section 2 | |\n| Where does the SafeVoice app and its SQLite file run? | The SQLite file holds the full records (section 3) | |\n| Which local FDP do we register with? | Needs its endpoint and metadata profile; `python -m src.fdp.metadata` prepares the metadata | |\n| Which licence or rights statement describes the data? | A legal decision; `SAFEVOICE_LICENSE` stays empty until agreed | |\n| Who is the publisher / data owner in the metadata? | `SAFEVOICE_PUBLISHER` | |\n\n## 2. What the host has to provide (W4-04: not done by the application)\n\n- **Encryption at rest** of the disks that hold the SQLite file, the audit log and the AllegroGraph repository.\n- **Encrypted backups**, with the encryption keys kept apart from the backups, and a tested restore.\n- **Transport encryption**: AllegroGraph is already reached over HTTPS (port 443). The Streamlit app must be put\n  behind HTTPS too (reverse proxy); the demo login is not production authentication.\n- **Access**: only named administrators can log in to the server; least-privilege file permissions on `data/` and `.env`.\n- **AllegroGraph accounts**: the application uses one account. Give it write access to its repository only, no\n  repository creation (`AG_CREATE_REPO=false`), and keep other accounts read-only.\n- **Retention and deletion**: agree how long records are kept and who may delete them (`python -m src.storage.admin\n  drop-user NAME` removes a user's graph; the SQLite rows and audit log are separate).\n- **Monitoring**: who reads `data/audit/audit.log` and checks `python -m ui.audit verify`.\n\n## 3. What the application does itself\n\n| Control | How | Switch |\n|---|---|---|\n| Login and ownership | Hashed passwords from `.env`, every query filtered by the logged-in user | `SAFEVOICE_USERS` |\n| Brute-force lockout | 5 failures lock a user name for 15 minutes (in memory) | `SAFEVOICE_MAX_ATTEMPTS`, `SAFEVOICE_LOCKOUT_MINUTES` |\n| One graph per user in AllegroGraph | `<graph base>/<user>` | `SAFEVOICE_GRAPH_BASE` |\n| Encrypted database columns | Fernet: titles, narratives, reasons, data, topic titles | `SAFEVOICE_DB_KEY`, `python -m ui.secure migrate` |\n| Tamper-evident records | Keyed hash per record | `SAFEVOICE_INTEGRITY_KEY`, `python -m ui.secure sealhash`, `SAFEVOICE_INTEGRITY_STRICT=true` |\n| Tamper-evident audit log | Every line holds the hash of the line before | `python -m ui.audit verify` |\n| Shape validation before upload | HDS shapes plus our extension shapes | `SAFEVOICE_VALIDATE_RDF` |\n| Coordinates generalised | Rounded to 3 decimals (about 110 m) when saved | fixed |\n\nKeys: keep `SAFEVOICE_DB_KEY` and `SAFEVOICE_INTEGRITY_KEY` outside the database folder and back them up. Without\nthe database key encrypted rows cannot be read.\n\n## 4. Privacy risks that remain (documented limitations)\n\n- **Free text is not de-identified.** The narrative, victim and trafficker descriptions, place names, a trafficker's\n  name or alias and the publication details can identify people, places or sources. The form says \"non-identifying\n  details only\", but nothing checks it. A human review step or guidance for reporters is needed.\n- **Coordinates to about 110 m, plus dates and a small group size, can still single out a person or a camp.**\n  Rounding is generalisation, not anonymisation. Re-identification risk has not been assessed.\n- **Older records** keep the precision they were saved with: changing them would break their integrity hash.\n- **The reporter's user name** is written to the shared graph (`dcterms:identifier` on the reporting agent) so the\n  source of a record is traceable. If user names are real names, use pseudonyms or an organisation ID.\n- **The demo login** has no password reset, no second factor and no session expiry beyond idle logout.\n- **Keys in `.env`** are readable by anyone who can read the file. Use the host's secret store in production.\n- **The audit log** is tamper-evident, not tamper-proof: removing lines from the end is not detectable from the log alone.\n",
 "tests/test_cdm_alignment.py": "\"\"\"The mapping layers stay in their lanes: the core file uses only terms from the HDS CDM, every term of our\nown extension is declared, and no mapping uses an hds: term that does not exist (typos).\"\"\"\nimport re\n\nimport yaml\nfrom rdflib import Graph, URIRef\nfrom rdflib.namespace import DCTERMS, FOAF, PROV, RDF, RDFS\n\nfrom src.transform import mapper\n\nHDS = \"https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl#\"\nCDM_EXT = \"https://w3id.org/dsip/cdm/\"\nSCHEMA = \"http://schema.org/\"\n\n# Non-hds terms that the CDM itself uses (see config/hds/hds-cdm-shapes.ttl and the HDS diagram).\nCDM_EXTERNAL = {str(t) for t in (\n    RDF.type, RDFS.label, DCTERMS.description, DCTERMS.isPartOf, DCTERMS.Location, FOAF.name, PROV.Agent,\n    URIRef(SCHEMA + \"location\"), URIRef(SCHEMA + \"startDate\"), URIRef(SCHEMA + \"endDate\"))}\n\n\ndef _expand(term, prefixes):\n    if term == \"a\":\n        return str(RDF.type)\n    prefix, _, local = str(term).partition(\":\")\n    return prefixes[prefix] + local if prefix in prefixes else str(term)\n\n\ndef _terms(path, prefixes):\n    \"\"\"Every predicate and every class used in one mapping file, as full IRIs.\"\"\"\n    mappings = yaml.safe_load(open(path, encoding=\"utf-8\"))[\"mappings\"]\n    used = set()\n    for cfg in mappings.values():\n        for po in cfg[\"po\"]:\n            pred, obj = (po[\"p\"], po[\"o\"]) if isinstance(po, dict) else (po[0], po[1])\n            used.add(_expand(pred, prefixes))\n            if pred == \"a\":\n                used.add(_expand(obj, prefixes))\n    return used\n\n\ndef _prefixes():\n    return mapper.load_mapping_config()[0]\n\n\ndef _declared(path):\n    return {str(s) for s in Graph().parse(path, format=\"turtle\").subjects() if isinstance(s, URIRef)}\n\n\ndef test_core_mapping_uses_only_terms_from_the_hds_cdm():\n    declared = _declared(\"config/hds/hds-cdm.ttl\")\n    outside = {t for t in _terms(\"config/mapping_core.yml\", _prefixes())\n               if t not in CDM_EXTERNAL and t not in declared}\n    assert outside == set(), f\"terms in mapping_core.yml that the HDS CDM does not define: {sorted(outside)}\"\n\n\ndef test_core_purity_check_catches_an_extra_term():\n    prefixes = _prefixes()\n    declared = _declared(\"config/hds/hds-cdm.ttl\")\n    assert _expand(\"cdm:age\", prefixes) not in declared | CDM_EXTERNAL\n    assert _expand(\"schema:nationality\", prefixes) not in declared | CDM_EXTERNAL\n\n\ndef test_every_extension_term_is_declared():\n    prefixes = _prefixes()\n    declared = _declared(\"config/safevoice-extension.ttl\")\n    used = set()\n    for path in (\"config/mapping_core.yml\", \"config/mapping_application.yml\"):\n        used |= {t for t in _terms(path, prefixes) if t.startswith(CDM_EXT)}\n    for path in (\"config/mapping_core.yml\", \"config/mapping_application.yml\"):\n        text = open(path, encoding=\"utf-8\").read()\n        used |= {_expand(m, prefixes) for m in re.findall(r\"\\bcdm:\\w+\", text)}\n    assert used and used <= declared, f\"cdm: terms used but not declared: {sorted(used - declared)}\"\n\n\ndef test_every_hds_term_in_the_mappings_exists_in_the_cdm():\n    declared = _declared(\"config/hds/hds-cdm.ttl\")\n    for path in (\"config/mapping_core.yml\", \"config/mapping_application.yml\"):\n        names = set(re.findall(r\"\\bhds:(\\w+)\", open(path, encoding=\"utf-8\").read()))\n        missing = {n for n in names if HDS + n not in declared}\n        assert missing == set(), f\"{path} uses hds: terms the CDM does not define: {sorted(missing)}\"\n\n\ndef test_the_domain_tag_is_a_concept_of_the_cdm_scheme():\n    g = Graph().parse(\"config/hds/hds-cdm.ttl\", format=\"turtle\")\n    tag = URIRef(HDS + \"humanTrafficking\")\n    assert (tag, RDF.type, URIRef(\"http://www.w3.org/2004/02/skos/core#Concept\")) in g\n    assert (tag, URIRef(\"http://www.w3.org/2004/02/skos/core#inScheme\"), URIRef(HDS + \"incidentDomainScheme\")) in g\n\n\ndef test_old_incident_domain_file_is_gone():\n    import os\n    assert not os.path.exists(\"config/hds/incident-domains.ttl\")\n",
 "tests/test_audit_integrity.py": "\"\"\"Audit log hash chain and keyed record hashes (W3-05).\"\"\"\nimport json\nimport sqlite3\n\nimport pytest\n\nfrom ui import audit, secure, store\n\n\n@pytest.fixture(autouse=True)\ndef isolated(tmp_path, monkeypatch):\n    monkeypatch.setattr(audit, \"AUDIT_LOG\", str(tmp_path / \"audit\" / \"audit.log\"))\n    monkeypatch.setattr(store, \"DB_PATH\", str(tmp_path / \"app\" / \"t.db\"))\n    monkeypatch.setattr(store, \"run_pipeline\", lambda df: (df, \"Success\"))\n    monkeypatch.setattr(audit, \"load_dotenv\", lambda *a, **k: None)\n    monkeypatch.setattr(secure, \"load_dotenv\", lambda *a, **k: None)\n    for var in (\"SAFEVOICE_INTEGRITY_KEY\", \"SAFEVOICE_INTEGRITY_STRICT\", \"SAFEVOICE_DB_KEY\"):\n        monkeypatch.delenv(var, raising=False)\n\n\ndef _lines():\n    return open(audit.AUDIT_LOG, encoding=\"utf-8\").read().splitlines()\n\n\ndef _write(lines):\n    import os\n    os.makedirs(os.path.dirname(audit.AUDIT_LOG), exist_ok=True)\n    open(audit.AUDIT_LOG, \"w\", encoding=\"utf-8\").write(\"\\n\".join(lines) + \"\\n\")\n\n\ndef _log(n=5):\n    for i in range(n):\n        audit.log(\"alice\", \"action\", f\"R-{i}\", f\"detail {i}\")\n\n\n# ---------------------------------------------------------------- audit log chain\n\ndef test_an_untouched_log_verifies():\n    _log()\n    assert audit.verify_log() == (True, None, 5)\n    assert json.loads(_lines()[0])[\"prev\"] == \"\" and json.loads(_lines()[1])[\"prev\"] != \"\"\n\n\ndef test_an_empty_or_missing_log_verifies():\n    assert audit.verify_log() == (True, None, 0)\n\n\ndef test_an_edited_line_is_found():\n    _log()\n    lines = _lines()\n    lines[2] = lines[2].replace(\"detail 2\", \"detail X\")\n    _write(lines)\n    assert audit.verify_log() == (False, 4, 5)  # the line after the edited one no longer matches\n\n\ndef test_a_removed_line_is_found():\n    _log()\n    lines = _lines()\n    del lines[1]\n    _write(lines)\n    ok, bad, _ = audit.verify_log()\n    assert not ok and bad == 2\n\n\ndef test_an_inserted_line_is_found():\n    _log()\n    lines = _lines()\n    lines.insert(2, json.dumps({\"time\": \"x\", \"user\": \"mallory\", \"action\": \"login\", \"record_id\": None, \"detail\": \"\"}))\n    _write(lines)\n    assert audit.verify_log()[0] is False\n\n\ndef test_old_lines_without_a_chain_are_accepted_and_the_chain_starts_after_them():\n    _write([json.dumps({\"time\": \"t\", \"user\": \"a\", \"action\": \"old\", \"record_id\": None, \"detail\": \"\"})] * 2)\n    _log(3)\n    assert audit.verify_log() == (True, None, 5)\n\n\ndef test_a_garbled_line_is_found():\n    _log(2)\n    _write(_lines() + [\"not json\"])\n    assert audit.verify_log()[:2] == (False, 3)\n\n\ndef test_concurrent_writers_keep_the_chain_intact():\n    import threading\n    threads = [threading.Thread(target=_log, args=(10,)) for _ in range(4)]\n    [t.start() for t in threads]\n    [t.join() for t in threads]\n    assert audit.verify_log() == (True, None, 40)\n\n\n# ---------------------------------------------------------------- keyed record hashes\n\ndef _submit():\n    topic = store.create_topic(\"alice\", \"T\", \"\")\n    return store.submit_record(\"alice\", topic[\"id\"], \"Title\", \"Narrative\", {\"victim\": {\"age\": 3}})\n\n\ndef _tamper(record_id):\n    with sqlite3.connect(store.DB_PATH) as db:\n        db.execute(\"UPDATE records SET narrative = 'changed' WHERE id = ?\", (record_id,))\n\n\ndef test_without_a_key_hashes_are_plain_as_before():\n    rec = _submit()\n    assert not rec[\"hash\"].startswith(\"hmac:\") and len(rec[\"hash\"]) == 64 and store.verify_record(rec)\n\n\ndef test_with_a_key_new_records_get_a_keyed_hash(monkeypatch):\n    monkeypatch.setenv(\"SAFEVOICE_INTEGRITY_KEY\", \"k\" * 32)\n    rec = _submit()\n    assert rec[\"hash\"].startswith(\"hmac:\") and store.verify_record(store.get_record(\"alice\", rec[\"id\"]))\n    _tamper(rec[\"id\"])\n    assert not store.verify_record(store.get_record(\"alice\", rec[\"id\"]))\n\n\ndef test_a_keyed_hash_cannot_be_recomputed_without_the_key(monkeypatch):\n    monkeypatch.setenv(\"SAFEVOICE_INTEGRITY_KEY\", \"k\" * 32)\n    rec = _submit()\n    _tamper(rec[\"id\"])\n    forged = audit.plain_hash(store.get_record(\"alice\", rec[\"id\"]))  # what someone with only the database can do\n    with sqlite3.connect(store.DB_PATH) as db:\n        db.execute(\"UPDATE records SET hash = ? WHERE id = ?\", (forged, rec[\"id\"]))\n    assert store.verify_record(store.get_record(\"alice\", rec[\"id\"]))  # non-strict mode still accepts a plain hash\n    monkeypatch.setenv(\"SAFEVOICE_INTEGRITY_STRICT\", \"true\")\n    assert not store.verify_record(store.get_record(\"alice\", rec[\"id\"]))  # strict mode does not\n\n\ndef test_wrong_or_missing_key_fails_the_check(monkeypatch):\n    monkeypatch.setenv(\"SAFEVOICE_INTEGRITY_KEY\", \"k\" * 32)\n    rec = _submit()\n    monkeypatch.setenv(\"SAFEVOICE_INTEGRITY_KEY\", \"z\" * 32)\n    assert not store.verify_record(store.get_record(\"alice\", rec[\"id\"]))\n    monkeypatch.delenv(\"SAFEVOICE_INTEGRITY_KEY\")\n    assert not store.verify_record(store.get_record(\"alice\", rec[\"id\"]))\n\n\ndef test_sealing_converts_good_plain_hashes_and_skips_tampered_ones(monkeypatch):\n    good, bad = _submit(), _submit()\n    _tamper(bad[\"id\"])\n    with pytest.raises(secure.KeyMissingError):\n        store.seal_hashes()\n    monkeypatch.setenv(\"SAFEVOICE_INTEGRITY_KEY\", \"k\" * 32)\n    assert store.seal_hashes() == (1, 1)\n    assert store.get_record(\"alice\", good[\"id\"])[\"hash\"].startswith(\"hmac:\")\n    assert store.verify_record(store.get_record(\"alice\", good[\"id\"]))\n    assert not store.get_record(\"alice\", bad[\"id\"])[\"hash\"].startswith(\"hmac:\")  # not hidden by re-hashing\n    assert not store.verify_record(store.get_record(\"alice\", bad[\"id\"]))\n    assert store.seal_hashes() == (0, 1)\n",
 "tests/test_tools.py": "\"\"\"Clean-up, resend, mock data and FDP metadata tools. All use the real mapping and the real HDS shapes;\nonly AllegroGraph is faked.\"\"\"\nimport pytest\nfrom rdflib import Graph\nfrom rdflib.namespace import DCTERMS, RDF\n\nfrom src.fdp import metadata\nfrom src.orchestrator import pipeline\nfrom src.storage import admin, ingest\nfrom src.transform import mapper\nfrom src.validation import shacl\nfrom ui import audit, auth, mockdata, resync, store\n\n\n@pytest.fixture(autouse=True)\ndef isolated(tmp_path, monkeypatch):\n    monkeypatch.setattr(store, \"DB_PATH\", str(tmp_path / \"app\" / \"t.db\"))\n    monkeypatch.setattr(audit, \"AUDIT_LOG\", str(tmp_path / \"audit\" / \"audit.log\"))\n    monkeypatch.setattr(mapper, \"INTERMEDIATE_DIR\", str(tmp_path / \"intermediate\"))\n    monkeypatch.setattr(pipeline, \"PROCESSED_NT_DIR\", str(tmp_path / \"processed\"))\n    (tmp_path / \"processed\").mkdir()\n    uploads = []\n    monkeypatch.setattr(pipeline, \"ingest_rdf_file\", lambda path, source_id: uploads.append((source_id, open(path).read())) or True)\n    return uploads\n\n\n# ---------------------------------------------------------------- mock data\n\ndef test_mock_records_pass_the_whole_pipeline_including_the_hds_shapes(isolated):\n    stored = mockdata.generate(\"alice\", records=12)\n    assert len(stored) == 12 and all(r[\"sync_status\"] == store.SYNCED for r in stored)\n    assert len(isolated) == 12 and all(source == \"alice\" for source, _ in isolated)\n    assert all(r[\"title\"].startswith(\"[MOCK]\") and \"not based on a real case\" in r[\"narrative\"] for r in stored)\n    assert any(r[\"corrects\"] for r in stored)  # some corrections are included\n    assert any(not r[\"data\"].get(\"incident\") for r in stored)  # some records are minimal\n\n\ndef test_mock_data_is_repeatable_and_belongs_to_one_user():\n    a = [r[\"data\"] for r in mockdata.generate(\"alice\", 6, seed=3)]\n    b = [r[\"data\"] for r in mockdata.generate(\"bob\", 6, seed=3)]\n    assert a == b and store.get_topics(\"alice\") and len(store.get_topics(\"bob\")) == 2\n    assert all(t[\"owner\"] == \"alice\" for t in store.get_topics(\"alice\"))\n\n\ndef test_mock_data_can_be_created_without_uploading(isolated):\n    stored = mockdata.generate(\"alice\", records=4, upload=False)\n    assert isolated == [] and all(r[\"sync_status\"] == store.NOT_SYNCED for r in stored)\n    store.resync_all(\"alice\")\n    assert len(isolated) == 4\n\n\n# ---------------------------------------------------------------- resend\n\ndef test_resync_sends_everything_again_or_only_what_is_missing(isolated, monkeypatch):\n    mockdata.generate(\"alice\", records=3)\n    mockdata.generate(\"bob\", records=2)\n    isolated.clear()\n    assert store.resync_all() == (5, 0) and len(isolated) == 5\n    isolated.clear()\n    assert store.resync_all(\"bob\") == (2, 0) and {s for s, _ in isolated} == {\"bob\"}\n    isolated.clear()\n    assert store.resync_all(only_unsynced=True) == (0, 0) and isolated == []\n\n\ndef test_resync_reports_failures(isolated, monkeypatch):\n    mockdata.generate(\"alice\", records=2)\n    monkeypatch.setattr(pipeline, \"ingest_rdf_file\", lambda path, source_id: False)\n    assert store.resync_all() == (0, 2)\n    monkeypatch.setattr(pipeline, \"ingest_rdf_file\", lambda path, source_id: True)\n    assert store.resync_all(only_unsynced=True) == (2, 0)\n\n\ndef test_resync_command_line(isolated, capsys):\n    mockdata.generate(\"alice\", records=2)\n    assert resync.main([\"--user\", \"alice\"]) == 0\n    assert \"2 in the database\" in capsys.readouterr().out\n\n\n# ---------------------------------------------------------------- AllegroGraph admin\n\nclass _Conn:\n    def __init__(self):\n        self.removed, self.closed = [], False\n\n    def createURI(self, iri):\n        return (\"URI\", iri)\n\n    def getContextIDs(self):\n        return [\"<https://x/graph/bob>\", \"<https://x/graph/alice>\"]\n\n    def size(self, ctx):\n        if ctx == \"<https://x/graph/bob>\":\n            raise RuntimeError(\"no size\")\n        return 7\n\n    def remove(self, s, p, o, contexts=None):\n        self.removed.append(contexts)\n\n    def close(self):\n        self.closed = True\n\n\ndef test_graphs_are_listed_even_when_a_size_is_unavailable():\n    assert admin.list_graphs(_Conn()) == [(\"https://x/graph/alice\", 7), (\"https://x/graph/bob\", None)]\n\n\ndef test_only_the_named_users_graph_is_dropped():\n    conn = _Conn()\n    graph = admin.drop_user_graph(conn, \"alice\")\n    assert conn.removed == [[(\"URI\", ingest.graph_for_source(\"alice\"))]] and graph.endswith(\"/alice\")\n\n\n@pytest.mark.parametrize(\"bad\", [\"../x\", \"a b\", \"\", \"*\", \"x>y\"])\ndef test_drop_refuses_anything_but_a_plain_user_name(bad):\n    conn = _Conn()\n    with pytest.raises(ValueError):\n        admin.drop_user_graph(conn, bad)\n    assert conn.removed == []\n\n\ndef test_drop_command_asks_for_the_name_and_cancels_otherwise(monkeypatch, capsys):\n    conn = _Conn()\n    monkeypatch.setattr(ingest, \"missing_settings\", lambda: [])\n    monkeypatch.setattr(ingest, \"connect\", lambda: conn)\n    monkeypatch.setattr(\"builtins.input\", lambda prompt: \"wrong\")\n    assert admin.main([\"drop-user\", \"alice\"]) == 1 and conn.removed == [] and conn.closed\n    monkeypatch.setattr(\"builtins.input\", lambda prompt: \"alice\")\n    assert admin.main([\"drop-user\", \"alice\"]) == 0 and len(conn.removed) == 1\n\n\n# ---------------------------------------------------------------- FDP metadata\n\ndef test_fdp_metadata_conforms_to_the_hds_shapes():\n    g = metadata.build_metadata([\"alice\", \"bob\"], publisher=\"Test lab\", license_iri=\"https://example.org/rights/restricted\",\n                                endpoint=\"https://ag.example.com/repositories/R\", now=\"2026-11-25T10:00:00Z\")\n    assert shacl.validate_graph(g) == (True, \"\")\n    assert len(list(g.subjects(RDF.type, metadata.DCAT.Dataset))) == 2\n    assert len(list(g.subjects(RDF.type, metadata.DCAT.Catalog))) == 1\n    assert (metadata.EX.catalog_safevoice, DCTERMS.publisher, metadata.EX.agent_publisher) in g\n\n\ndef test_fdp_metadata_works_without_licence_and_endpoint_and_never_contains_content():\n    g = metadata.build_metadata([\"alice\"], license_iri=\"\", endpoint=\"\", now=\"2026-11-25T10:00:00Z\")\n    assert shacl.validate_graph(g)[0] and not list(g.objects(None, DCTERMS.license))\n    text = g.serialize(format=\"turtle\")\n    assert \"narrative\" not in text.lower() and \"password\" not in text.lower()\n\n\ndef test_fdp_metadata_rejects_an_unsafe_user_name():\n    with pytest.raises(ValueError):\n        metadata.build_metadata([\"../evil\"])\n\n\ndef test_fdp_metadata_with_a_licence_that_is_not_a_rights_statement_is_caught():\n    g = metadata.build_metadata([\"alice\"], license_iri=\"https://example.org/rights/x\", endpoint=\"\")\n    from rdflib import URIRef\n    g.remove((URIRef(\"https://example.org/rights/x\"), RDF.type, DCTERMS.RightsStatement))\n    assert not shacl.validate_graph(g)[0]\n"
}

REPLACE_FILES = {
 "config/hds/hds-cdm.ttl": "@prefix hds: <https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix dpv: <https://w3id.org/dpv#> .\n@prefix owl: <http://www.w3.org/2002/07/owl#> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\n@prefix schema: <http://schema.org/> .\n\n<https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl>\n    a owl:Ontology ;\n    rdfs:label \"HDS Centralized Common Data Model\"@en ;\n    dcterms:source \"HDS MIP_v2.pdf\" ;\n    owl:versionInfo \"Development profile based on HDS CDM V2; see README.md.\"@en .\n\n\n# Core hds terms\nhds:Incident a owl:Class ;\n    rdfs:label \"Incident\"@en ;\n    rdfs:subClassOf schema:Event .\n\n# Incident-domain vocabulary (centralised core terms)\n# Use these concepts as values of hds:incidentDomain. An incident can have more than one domain.\n\nhds:incidentDomainScheme a skos:ConceptScheme ;\n    dcterms:title \"HDS incident domains\"@en ;\n    dcterms:description \"A controlled vocabulary for classifying HDS incidents by domain. An incident may have multiple domains.\"@en ;\n    skos:hasTopConcept hds:environmental, hds:humanTrafficking,\n        hds:humanitarian, hds:humanRightsAbuse, hds:migration,\n        hds:military, hds:political, hds:sexualViolence .\n\nhds:environmental a skos:Concept ;\n    skos:prefLabel \"Environmental event\"@en ;\n    dcterms:description \"An incident involving natural hazards, environmental degradation, or damage to ecosystems.\"@en ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:humanTrafficking a skos:Concept ;\n    skos:prefLabel \"Human trafficking\"@en ;\n    dcterms:description \"An incident involving the recruitment, movement, harbouring, or receipt of people for exploitation through coercion, deception, or abuse of vulnerability, including child trafficking for which such means are not required.\"@en ;\n    hds:applicableProperty hds:casualties ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:humanitarian a skos:Concept ;\n    skos:prefLabel \"Humanitarian event\"@en ;\n    dcterms:description \"An incident affecting people's safety, basic needs, or access to essential services that creates or worsens a need for humanitarian assistance.\"@en ;\n    hds:applicableProperty hds:casualties ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:humanRightsAbuse a skos:Concept ;\n    skos:prefLabel \"Human rights abuse\"@en ;\n    dcterms:description \"An incident involving reported harm to or infringement of people's human rights and fundamental freedoms.\"@en ;\n    hds:applicableProperty hds:casualties ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:migration a skos:Concept ;\n    skos:prefLabel \"Migration event\"@en ;\n    dcterms:description \"An incident related to the movement of people within a country or across borders, including displacement, transit, arrival, or return.\"@en ;\n    hds:applicableProperty hds:casualties ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:military a skos:Concept ;\n    skos:prefLabel \"Military event\"@en ;\n    dcterms:description \"An incident involving military operations, armed hostilities, or activities of armed forces or armed groups.\"@en ;\n    hds:applicableProperty hds:weaponsUsed, hds:casualties ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:political a skos:Concept ;\n    skos:prefLabel \"Political event\"@en ;\n    dcterms:description \"An incident related to governance, political participation, elections, or the exercise of political power.\"@en ;\n    hds:applicableProperty hds:outcome ;\n    skos:inScheme hds:incidentDomainScheme .\n\nhds:sexualViolence a skos:Concept ;\n    skos:prefLabel \"Sexual violence\"@en ;\n    dcterms:description \"An incident involving a sexual act or attempted sexual act without freely given consent, including acts committed through force, threats, coercion, or abuse of power.\"@en ;\n    skos:inScheme hds:incidentDomainScheme .\n\n\n# Application specific terms (situation report)\nhds:Report a owl:Class ; \n    rdfs:label \"Situation report\"@en ;\n    rdfs:comment \"Individual incident records may be contained in a situation report using dcterms:isPartOf from the incident to the report.\"@en .\nhds:Camp a owl:Class ;\n    rdfs:label \"IDP or refugee camp\"@en ;\n    schema:location hds:humanRightsAbuse, hds:humanitarian ;\n    rdfs:comment \"The Camp class links to the human-rights-abuse and humanitarian domain concepts using schema:location in this HDS profile. Camp instances may separately reference geographical locations.\"@en .\nhds:MigrationRoute a owl:Class ;\n    rdfs:label \"Migration route\"@en ;\n    schema:location hds:humanTrafficking, hds:migration ;\n    rdfs:comment \"The MigrationRoute class links to the human-trafficking and migration domain concepts using schema:location in this HDS profile. Route instances may separately reference geographical locations.\"@en .\n\n\n# Object properties\nhds:applicableProperty a owl:AnnotationProperty ;\n    rdfs:label \"applicable incident property\"@en ;\n    rdfs:comment \"Links an incident-domain concept to an additional property applicable to incidents tagged with that domain. Values are recorded on incidents; this annotation does not impose required fields.\"@en .\nhds:involves a owl:ObjectProperty ; \n    rdfs:label \"involves\"@en ;\n    rdfs:range prov:Agent .\nhds:incidentDomain a owl:ObjectProperty ;\n    rdfs:label \"incident domain\"@en ;\n    rdfs:seeAlso hds:incidentDomainScheme .\nhds:reportedBy a owl:ObjectProperty ; \n    rdfs:label \"reported by\"@en ;\n    rdfs:range prov:Agent .\n\n# Datatype properties\nhds:actorType a owl:DatatypeProperty ; \n    rdfs:label \"actor type\"@en .\nhds:confidentiality a owl:DatatypeProperty ; \n    rdfs:label \"confidentiality\"@en .\nhds:victimCount a owl:DatatypeProperty ; \n    rdfs:label \"victim count\"@en .\nhds:status a owl:DatatypeProperty ; \n    rdfs:label \"status\"@en .\nhds:outcome a owl:DatatypeProperty ; \n    rdfs:label \"outcome\"@en .\nhds:casualties a owl:DatatypeProperty ; \n    rdfs:label \"casualties\"@en ;\n    rdfs:comment \"An incident casualty count. Whether this counts deaths, injuries, or both remains to be agreed. Omit an unknown count rather than representing it as zero.\"@en .\nhds:weaponsUsed a owl:DatatypeProperty ; \n    rdfs:label \"weapons used\"@en .\n",
 "config/hds/hds-cdm-shapes.ttl": "@prefix hds: <https://vodan-development.github.io/HDS-Centralized-Common-Data-Model/hds-cdm.ttl#> .\n@prefix shapes: <https://github.com/VODAN-Development/HDS-Centralized-Common-Data-Model#> .\n@prefix dcat: <http://www.w3.org/ns/dcat#> .\n@prefix dcterms: <http://purl.org/dc/terms/> .\n@prefix dpv: <https://w3id.org/dpv#> .\n@prefix foaf: <http://xmlns.com/foaf/0.1/> .\n@prefix owl: <http://www.w3.org/2002/07/owl#> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n@prefix schema: <http://schema.org/> .\n@prefix sh: <http://www.w3.org/ns/shacl#> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\n@prefix odrl: <http://www.w3.org/ns/odrl/2/> .\n@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n\n# SHACL expresses the profile's expected value types. All properties are \n# currently optional because no minimum cardinalities are expressed.\n\nshapes:IncidentShape a sh:NodeShape ;\n    sh:targetClass hds:Incident ;\n    sh:node shapes:PoliticalIncidentShape, shapes:CasualtyIncidentShape,\n        shapes:MilitaryIncidentShape ;\n    sh:property [\n        sh:path hds:involves ;\n        sh:class prov:Agent\n    ] ;\n    sh:property [\n        sh:path schema:location ;\n        sh:class dcterms:Location ;\n        sh:description \"An incident may reference geographical locations. Locations are optional and repeatable.\"@en\n    ] ;\n    # Load hds-cdm.ttl with the data for the class and scheme checks.\n    sh:property [\n        sh:path hds:incidentDomain ;\n        sh:nodeKind sh:IRI ;\n        sh:class skos:Concept ;\n        sh:property [\n            sh:path skos:inScheme ;\n            sh:hasValue hds:incidentDomainScheme\n        ]\n    ] ;\n    sh:property [ sh:path hds:reportedBy ; sh:class prov:Agent ] ;\n    sh:property [\n        sh:path dcterms:isPartOf ;\n        sh:or ( [ sh:class hds:Report ] [ sh:class dcat:Dataset ] )\n    ] ;\n    sh:property [ sh:path schema:startDate ; sh:datatype xsd:dateTime ] ;\n    sh:property [ sh:path schema:endDate ; sh:datatype xsd:dateTime ] ;\n    sh:property shapes:Description ;\n    sh:property [ sh:path hds:confidentiality ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path hds:victimCount ; sh:datatype xsd:integer ] ;\n    sh:property [ sh:path hds:status ; sh:datatype xsd:string ] .\n\nshapes:AgentShape a sh:NodeShape ;\n    sh:targetClass prov:Agent ;\n    sh:property [ sh:path hds:actorType ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path rdfs:label ; sh:node shapes:TextLiteral ] ;\n    sh:property [ sh:path foaf:name ; sh:node shapes:TextLiteral ] .\n\nshapes:CampShape a sh:NodeShape ;\n    sh:targetClass hds:Camp ;\n    sh:description \"Camp instances may reference geographical locations. These are distinct from the class-level links to incident-domain concepts.\"@en ;\n    sh:property [ sh:path schema:location ; sh:class dcterms:Location ] .\n\nshapes:MigrationRouteShape a sh:NodeShape ;\n    sh:targetClass hds:MigrationRoute ;\n    sh:description \"Route instances may reference geographical locations. These are distinct from the class-level links to incident-domain concepts.\"@en ;\n    sh:property [ sh:path schema:location ; sh:class dcterms:Location ] .\n\nshapes:LocationDomainLinksShape a sh:NodeShape ;\n    sh:targetNode hds:Camp, hds:MigrationRoute ;\n    sh:property [\n        sh:path schema:location ;\n        sh:nodeKind sh:IRI ;\n        sh:class skos:Concept ;\n        sh:property [ sh:path skos:inScheme ; sh:hasValue hds:incidentDomainScheme ]\n    ] .\n\n# These reusable shapes check field types on every incident, regardless of tag.\n# Applicable-property annotations describe relevance, not permission or requiredness.\nshapes:PoliticalIncidentShape a sh:NodeShape ;\n    sh:property [ sh:path hds:outcome ; sh:datatype xsd:string ] .\n\nshapes:CasualtyIncidentShape a sh:NodeShape ;\n    sh:property [ sh:path hds:casualties ; sh:datatype xsd:integer ] .\n\nshapes:MilitaryIncidentShape a sh:NodeShape ;\n    sh:property [ sh:path hds:weaponsUsed ; sh:datatype xsd:string ] .\n\n# Consent assignees use the same agent class as other actor references.\nshapes:ConsentShape a sh:NodeShape ;\n    sh:targetClass dpv:Consent ;\n    sh:property [ sh:path odrl:assignee ; sh:class prov:Agent ] ;\n    sh:property [ sh:path dcterms:accessRights ; sh:class prov:Agent ] ;\n    sh:property [ sh:path dpv:hasPurpose ; sh:class dpv:Purpose ] ;\n    sh:property [ sh:path dcterms:publisher ; sh:node shapes:PublisherAgentReference ] .\n\n# All agent roles, including publishers, use the same PROV class.\nshapes:PublisherAgentReference a sh:NodeShape ;\n    sh:description \"Publisher references must be typed as prov:Agent.\"@en ;\n    sh:nodeKind sh:BlankNodeOrIRI ;\n    sh:node shapes:AgentShape ;\n    sh:class prov:Agent .\n\n# License metadata applies to catalogues and datasets.\n# Purpose and policy links to governance resources are not part of this profile.\nshapes:RightsMetadataShape a sh:NodeShape ;\n    sh:targetClass dcat:Catalog, dcat:Dataset ;\n    sh:property [ sh:path dcterms:license ; sh:nodeKind sh:IRI ; sh:class dcterms:RightsStatement ] .\n\nshapes:CatalogMetadataShape a sh:NodeShape ;\n    sh:targetClass dcat:Catalog, dcat:Dataset ;\n    sh:property [ sh:path dcterms:publisher ; sh:node shapes:PublisherAgentReference ] ;\n    sh:property [ sh:path dcterms:license ; sh:nodeKind sh:IRI ; sh:class dcterms:RightsStatement ] ;\n    sh:property [ sh:path dcterms:conformsTo ; sh:nodeKind sh:IRI ] ;\n    sh:property [ sh:path dcterms:language ; sh:nodeKind sh:IRI ] ;\n    # Version labels are literals. dcterms:hasVersion links to a resource.\n    sh:property [ sh:path dcat:version ; sh:datatype xsd:string ] ;\n    sh:property [ sh:path dcterms:hasVersion ; sh:nodeKind sh:BlankNodeOrIRI ] .\n\nshapes:DatasetShape a sh:NodeShape ;\n    sh:targetClass dcat:Dataset ;\n    sh:property [ sh:path dcterms:isPartOf ; sh:class dcat:Catalog ] ;\n    sh:property [ sh:path dcat:distribution ; sh:class dcat:Distribution ] .\n\nshapes:ResourceMetadataShape a sh:NodeShape ;\n    sh:targetClass dcat:Catalog, dcat:Dataset, dcat:Distribution, hds:Report ;\n    sh:property shapes:Description ;\n    sh:property [ sh:path prov:generatedAtTime ; sh:datatype xsd:dateTime ] ;\n    sh:property [ sh:path schema:identifier ; sh:datatype xsd:anyURI ] ;\n    sh:property [ sh:path dcterms:title ; sh:node shapes:TextLiteral ] ;\n    sh:property [ sh:path dcterms:identifier ; sh:datatype xsd:string ] .\n\nshapes:LabelShape a sh:NodeShape ;\n    sh:targetClass hds:Incident, hds:Report, dcterms:Location, skos:Concept,\n        prov:Agent, dcat:Catalog, dcat:Dataset, dcat:Distribution ;\n    sh:property [ sh:path rdfs:label ; sh:node shapes:TextLiteral ] .\n\nshapes:Description a sh:PropertyShape ;\n    sh:path dcterms:description ;\n    sh:node shapes:TextLiteral .\n\nshapes:TextLiteral a sh:NodeShape ;\n    sh:or (\n        [ sh:datatype xsd:string ]\n        [ sh:datatype rdf:langString ]\n    ) .\n\n# Incident-domain SHACL validation\n# Validate the incident-domain vocabulary in hds-cdm.ttl.\n# Additional domains and translations are allowed.\n\nhds:IncidentDomainSchemeShape a sh:NodeShape ;\n    sh:targetNode hds:incidentDomainScheme ;\n    sh:nodeKind sh:IRI ;\n    sh:class skos:ConceptScheme ;\n    sh:property [\n        sh:path dcterms:title ;\n        sh:minCount 1 ;\n        sh:datatype rdf:langString ;\n        sh:uniqueLang true ;\n        sh:message \"The incident-domain scheme needs a language-tagged title, with at most one title per language.\"@en\n    ] ;\n    sh:property [\n        sh:path dcterms:description ;\n        sh:datatype rdf:langString ;\n        sh:uniqueLang true ;\n        sh:message \"Descriptions must be language-tagged, with at most one description per language.\"@en\n    ] ;\n    sh:property [\n        sh:path skos:hasTopConcept ;\n        sh:minCount 1 ;\n        sh:node hds:IncidentDomainConceptShape ;\n        sh:message \"Each top concept must be an IRI identifying a labelled concept in the incident-domain scheme.\"@en\n    ] .\n\nhds:IncidentDomainConceptShape a sh:NodeShape ;\n    # Relationship targets also catch concepts whose rdf:type was omitted.\n    sh:targetClass skos:Concept ;\n    sh:targetSubjectsOf skos:inScheme ;\n    sh:targetObjectsOf skos:hasTopConcept ;\n    sh:nodeKind sh:IRI ;\n    sh:class skos:Concept ;\n    sh:property [\n        sh:path hds:applicableProperty ;\n        sh:nodeKind sh:IRI ;\n        sh:or ( [ sh:class rdf:Property ] [ sh:class owl:DatatypeProperty ]\n            [ sh:class owl:ObjectProperty ] [ sh:class owl:AnnotationProperty ] ) ;\n        sh:message \"Applicable properties must be IRIs with an explicit RDF or OWL property declaration in the data graph.\"@en\n    ] ;\n    sh:property [\n        sh:path skos:prefLabel ;\n        sh:minCount 1 ;\n        sh:datatype rdf:langString ;\n        sh:uniqueLang true ;\n        sh:message \"Each incident domain needs a language-tagged preferred label, with at most one preferred label per language.\"@en\n    ] ;\n    sh:property [\n        sh:path dcterms:description ;\n        sh:datatype rdf:langString ;\n        sh:uniqueLang true ;\n        sh:message \"Descriptions must be language-tagged, with at most one description per language.\"@en\n    ] ;\n    sh:property [\n        sh:path skos:inScheme ;\n        sh:nodeKind sh:IRI ;\n        sh:hasValue hds:incidentDomainScheme ;\n        sh:message \"Each incident domain must belong to hds:incidentDomainScheme.\"@en\n    ] .\n"
}

DELETE_FILES = ["config/hds/incident-domains.ttl"]

def update_crosswalk(path, mappings):
    """Rewrite rdf_predicates (and rdf_scope / notes of the four formerly deferred rows) from the merged mapping."""
    import csv, io, re
    PH = re.compile(r"\$\((\w+)\)")
    uses = {}
    for name, cfg in mappings.items():
        for col in PH.findall(cfg["s"]):
            uses.setdefault(col, []).append(f"{name}: (node name)")
        for po in cfg["po"]:
            pred, obj = (po["p"], po["o"]) if isinstance(po, dict) else (po[0], po[1])
            for col in PH.findall(str(obj)):
                uses.setdefault(col, []).append(f"{name}: {pred}")
    raw = open(path, "rb").read().decode("utf-8")
    bom, crlf = raw.startswith("\ufeff"), "\r\n" in raw
    rows = list(csv.reader(io.StringIO(raw.lstrip("\ufeff").replace("\r\n", "\n"), newline="")))
    head = rows[0]; ix = {h: i for i, h in enumerate(head)}
    for r in rows[1:]:
        col = r[ix["flat_column"]]
        if col not in uses:
            continue
        r[ix["rdf_predicates"]] = " | ".join(dict.fromkeys(uses[col]))
        if r[ix["rdf_scope"]].startswith("deferred"):
            r[ix["rdf_scope"]] = "mapped"
            r[ix["notes"]] = "Mapped in P4 (HDS core and application mapping)."
    out = io.StringIO()
    csv.writer(out, lineterminator="\r\n" if crlf else "\n").writerows(rows)
    open(path, "wb").write((("\ufeff" if bom else "") + out.getvalue()).encode("utf-8"))


def main(check_only):
    plan, problems = [], []
    for path, pairs in EDITS.items():
        if not os.path.exists(path):
            problems.append(f"{path}: file not found (run this from the repository root, after updates 1 and 2)")
            continue
        raw = open(path, "rb").read().decode("utf-8")
        eol = "\r\n" if "\r\n" in raw else "\n"
        text, state = raw.replace("\r\n", "\n"), []
        for old, new in pairs:
            if text.count(new) >= 1 and text.count(old) == 0:
                state.append("done")
            elif text.count(old) == 1:
                text = text.replace(old, new)
                state.append("apply")
            else:
                lines = old.splitlines()
                problems.append(f"{path}: expected text not found exactly once near: {lines[min(3, len(lines) - 1)].strip()[:70]!r}")
                break
        else:
            plan.append((path, text.replace("\n", eol), state))
    if problems:
        print("NOTHING WAS CHANGED. Problems:")
        for p in problems:
            print("  -", p)
        print("Send me the current version of the file(s) above and I will adjust the changes.")
        return 1
    for path, content, state in plan:
        if state and all(s == "done" for s in state):
            print(f"  ok       {path} (already applied)")
        else:
            print(f"  {'would change' if check_only else 'changed'} {path}")
            if not check_only:
                with open(path, "wb") as fh:
                    fh.write(content.encode("utf-8"))
    win = sys.platform == "win32"
    for path, content in NEW_FILES.items():
        if os.path.exists(path):
            print(f"  skip     {path} (already exists)")
            continue
        print(f"  {'would create' if check_only else 'created'} {path}")
        if not check_only:
            os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
            with open(path, "wb") as fh:
                fh.write((content.replace("\n", "\r\n") if win else content).encode("utf-8"))
    for path, content in REPLACE_FILES.items():
        same = os.path.exists(path) and open(path, "rb").read().decode("utf-8").replace("\r\n", "\n") == content
        print(f"  ok       {path} (already the new version)" if same else f"  {'would replace' if check_only else 'replaced'} {path}")
        if not same and not check_only:
            os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
            with open(path, "wb") as fh:
                fh.write((content.replace("\n", "\r\n") if win else content).encode("utf-8"))
    for path in DELETE_FILES:
        if os.path.exists(path):
            print(f"  {'would delete' if check_only else 'deleted'} {path} (no longer part of the CDM)")
            if not check_only:
                os.remove(path)
    if not check_only:
        sys.path.insert(0, os.getcwd())
        from src.transform import mapper  # the merged core + application mapping
        _, mappings = mapper.load_mapping_config()
        update_crosswalk("config/field_crosswalk.csv", mappings)
        print("  changed  config/field_crosswalk.csv (rdf_predicates regenerated from the mapping)")
    print("Done. Restart Streamlit, then run pytest." if not check_only else "Check passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main("--check" in sys.argv))